"use client"

import { useState, useEffect } from "react"
import { Button } from "@/components/ui/button"
import { MapMarker } from "@/components/map-marker"
import { Plus, Minus, Locate, Layers, Navigation, Star, Phone } from "lucide-react"
import type { Destination, NearbyPlace } from "@/lib/google-maps-service"

interface MapLocation {
  id: string
  name: string
  lat: number
  lng: number
  type: "destination" | "food" | "event" | "hotel" | "attraction"
}

const mockLocations: MapLocation[] = [
  { id: "1", name: "Eiffel Tower", lat: 48.8584, lng: 2.2945, type: "attraction" },
  { id: "2", name: "Le Petit Bistro", lat: 48.8566, lng: 2.3522, type: "food" },
  { id: "3", name: "Grand Hotel Paris", lat: 48.869, lng: 2.332, type: "hotel" },
  { id: "4", name: "Louvre Museum", lat: 48.8606, lng: 2.3376, type: "attraction" },
  { id: "5", name: "Jazz Festival", lat: 48.8738, lng: 2.295, type: "event" },
  { id: "6", name: "Notre-Dame", lat: 48.853, lng: 2.3499, type: "destination" },
]

interface InteractiveMapProps {
  onMarkerClick?: (location: MapLocation) => void
  selectedId?: string
  searchDestination?: Destination | null
  nearbyPlaces?: NearbyPlace[]
}

export function InteractiveMap({ 
  onMarkerClick, 
  selectedId, 
  searchDestination,
  nearbyPlaces = [] 
}: InteractiveMapProps) {
  const [zoom, setZoom] = useState(100)
  const [mapCenter, setMapCenter] = useState({ lat: 48.8584, lng: 2.2945 })
  const [selectedNearbyPlace, setSelectedNearbyPlace] = useState<NearbyPlace | null>(null)

  // Center map on search destination
  useEffect(() => {
    if (searchDestination) {
      setMapCenter({
        lat: searchDestination.location.lat,
        lng: searchDestination.location.lng
      })
      setZoom(120)
    }
  }, [searchDestination])

  const handleZoomIn = () => setZoom((prev) => Math.min(prev + 20, 200))
  const handleZoomOut = () => setZoom((prev) => Math.max(prev - 20, 50))

  // Convert lat/lng to screen position
  const latLngToPosition = (lat: number, lng: number) => {
    const centerLat = searchDestination?.location.lat || 48.8584
    const centerLng = searchDestination?.location.lng || 2.2945
    
    return {
      left: `${50 + (lng - centerLng) * 500}%`,
      top: `${50 - (lat - centerLat) * 500}%`,
    }
  }

  return (
    <div className="relative w-full h-full bg-secondary/20 overflow-hidden">
      {/* Mock map background */}
      <div
        className="absolute inset-0 transition-transform duration-300"
        style={{
          transform: `scale(${zoom / 100})`,
          backgroundImage: `url('/abstract-travel-pattern-world-map-dots.jpg')`,
          backgroundSize: "cover",
          backgroundPosition: "center",
        }}
      >
        {/* Map grid overlay */}
        <div
          className="absolute inset-0 opacity-10"
          style={{
            backgroundImage: `
              linear-gradient(to right, currentColor 1px, transparent 1px),
              linear-gradient(to bottom, currentColor 1px, transparent 1px)
            `,
            backgroundSize: "50px 50px",
          }}
        />

        {/* Search destination marker */}
        {searchDestination && (
          <div
            className="absolute transform -translate-x-1/2 -translate-y-1/2 transition-all z-20"
            style={latLngToPosition(
              searchDestination.location.lat,
              searchDestination.location.lng
            )}
          >
            <div className="relative">
              <div className="w-8 h-8 bg-red-500 rounded-full animate-pulse shadow-lg flex items-center justify-center">
                <Locate className="h-4 w-4 text-white" />
              </div>
              <div className="absolute -bottom-8 left-1/2 transform -translate-x-1/2 whitespace-nowrap bg-background/90 backdrop-blur-sm px-2 py-1 rounded text-xs font-medium shadow-lg">
                {searchDestination.name}
              </div>
            </div>
          </div>
        )}

        {/* Nearby places markers */}
        {nearbyPlaces.map((place) => {
          const position = latLngToPosition(place.location.lat, place.location.lng)
          const isSelected = selectedNearbyPlace?.id === place.id
          
          return (
            <div
              key={place.id}
              className="absolute transform -translate-x-1/2 -translate-y-1/2 transition-all cursor-pointer z-10"
              style={position}
              onClick={() => setSelectedNearbyPlace(isSelected ? null : place)}
            >
              <div className={`relative ${isSelected ? 'scale-125' : 'hover:scale-110'} transition-transform`}>
                <div className={`w-6 h-6 rounded-full shadow-lg flex items-center justify-center ${
                  place.category === 'restaurant' ? 'bg-orange-500' :
                  place.category === 'hotel' ? 'bg-blue-500' :
                  place.category === 'food_stall' ? 'bg-yellow-500' :
                  place.category === 'hospital' ? 'bg-red-600' :
                  place.category === 'atm' ? 'bg-green-600' :
                  'bg-purple-500'
                }`}>
                  {place.category === 'restaurant' && '🍽️'}
                  {place.category === 'hotel' && '🏨'}
                  {place.category === 'food_stall' && '☕'}
                  {place.category === 'hospital' && '🏥'}
                  {place.category === 'atm' && '🏧'}
                  {place.category === 'gas_station' && '⛽'}
                  {place.category === 'pharmacy' && '💊'}
                  {place.category === 'tourist_attraction' && '🎯'}
                </div>
                
                {/* Place info popup */}
                {isSelected && (
                  <div className="absolute top-8 left-1/2 transform -translate-x-1/2 w-64 bg-background border rounded-lg shadow-xl p-3 z-30">
                    <div className="space-y-2">
                      <div>
                        <h3 className="font-semibold text-sm">{place.name}</h3>
                        <p className="text-xs text-muted-foreground line-clamp-1">{place.address}</p>
                      </div>
                      
                      <div className="flex items-center gap-3 text-xs">
                        <div className="flex items-center gap-1 text-yellow-600">
                          <Star className="h-3 w-3 fill-current" />
                          <span>{place.rating}</span>
                        </div>
                        <div className="flex items-center gap-1 text-muted-foreground">
                          <Navigation className="h-3 w-3" />
                          <span>{place.distance}</span>
                        </div>
                      </div>

                      {place.phoneNumber && (
                        <Button 
                          variant="outline" 
                          size="sm" 
                          className="w-full text-xs"
                          onClick={(e) => {
                            e.stopPropagation()
                            window.open(`tel:${place.phoneNumber}`, '_blank')
                          }}
                        >
                          <Phone className="h-3 w-3 mr-1" />
                          Call Now
                        </Button>
                      )}
                    </div>
                  </div>
                )}
              </div>
            </div>
          )
        })}

        {/* Original mock markers (only show if no search active) */}
        {!searchDestination && mockLocations.map((location) => (
          <div
            key={location.id}
            className="absolute transform -translate-x-1/2 -translate-y-1/2 transition-all"
            style={{
              left: `${30 + (location.lng - 2.2) * 200}%`,
              top: `${70 - (location.lat - 48.85) * 500}%`,
            }}
          >
            <MapMarker
              type={location.type}
              selected={selectedId === location.id}
              onClick={() => onMarkerClick?.(location)}
            />
          </div>
        ))}
      </div>

      {/* Map controls */}
      <div className="absolute right-4 top-4 flex flex-col gap-2">
        <Button variant="secondary" size="icon" onClick={handleZoomIn} className="shadow-lg">
          <Plus className="h-4 w-4" />
        </Button>
        <Button variant="secondary" size="icon" onClick={handleZoomOut} className="shadow-lg">
          <Minus className="h-4 w-4" />
        </Button>
        <div className="h-px bg-border my-1" />
        <Button 
          variant="secondary" 
          size="icon" 
          className="shadow-lg"
          onClick={() => {
            if (searchDestination) {
              setMapCenter({
                lat: searchDestination.location.lat,
                lng: searchDestination.location.lng
              })
              setZoom(120)
            }
          }}
        >
          <Locate className="h-4 w-4" />
        </Button>
        <Button variant="secondary" size="icon" className="shadow-lg">
          <Layers className="h-4 w-4" />
        </Button>
      </div>

      {/* Zoom level indicator */}
      <div className="absolute left-4 bottom-4 px-3 py-1.5 bg-background/80 backdrop-blur-sm rounded-full text-sm">
        Zoom: {zoom}%
      </div>

      {/* Legend */}
      <div className="absolute right-4 bottom-4 p-3 bg-background/80 backdrop-blur-sm rounded-lg text-xs space-y-1.5">
        {searchDestination ? (
          <>
            <div className="font-semibold mb-2 text-sm">Nearby Places</div>
            <div className="flex items-center gap-2">
              <span className="text-base">🍽️</span>
              <span>Restaurants</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-base">🏨</span>
              <span>Hotels</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-base">☕</span>
              <span>Cafes</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-base">🏥</span>
              <span>Hospitals</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="text-base">🏧</span>
              <span>ATMs</span>
            </div>
          </>
        ) : (
          <>
            <div className="flex items-center gap-2">
              <span className="w-3 h-3 rounded-full bg-primary" />
              <span>Destinations</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="w-3 h-3 rounded-full bg-accent" />
              <span>Food</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="w-3 h-3 rounded-full bg-chart-3" />
              <span>Events</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="w-3 h-3 rounded-full bg-chart-4" />
              <span>Hotels</span>
            </div>
          </>
        )}
      </div>
    </div>
  )
}
